import json
import sys
from pathlib import Path

STORE = Path("todo.json")


def load():
    if not STORE.exists():
        return []
    return json.loads(STORE.read_text())


def save(items):
    STORE.write_text(json.dumps(items))


def cmd_add(args):
    if not args:
        print("Error: missing text", file=sys.stderr)
        sys.exit(1)
    text = " ".join(args)
    items = load()
    next_id = max((item["id"] for item in items), default=0) + 1
    items.append({"id": next_id, "text": text, "done": False})
    save(items)
    print(f"Added #{next_id}: {text}")


def cmd_list(args):
    items = load()
    if not items:
        print("No todos.")
        return
    for item in items:
        mark = "x" if item["done"] else " "
        print(f"[{mark}] {item['id']}: {item['text']}")


def cmd_done(args):
    try:
        todo_id = int(args[0])
    except (IndexError, ValueError):
        print("Error: invalid id", file=sys.stderr)
        sys.exit(1)
    items = load()
    for item in items:
        if item["id"] == todo_id:
            item["done"] = True
            save(items)
            print(f"Done #{todo_id}")
            return
    print(f"Error: no todo with id {todo_id}", file=sys.stderr)
    sys.exit(1)


COMMANDS = {"add": cmd_add, "list": cmd_list, "done": cmd_done}


def main():
    if len(sys.argv) < 2 or sys.argv[1] not in COMMANDS:
        print("Usage: todo <add|list|done> ...", file=sys.stderr)
        sys.exit(1)
    COMMANDS[sys.argv[1]](sys.argv[2:])


if __name__ == "__main__":
    main()

